#!/bin/sh
# kodi-rt: TARGET C compiler for FFmpeg's configure, desktop Windows x86: clang-cl rt2.4 f6e5f8e0, MSVC ABI, /MT,
# SDK 10.0.26100.0. Generated by cross/gen-arch-files.py; edit that, not this. (Never pass the rsp via --extra-cflags: configure feeds those to the assembler too.)
exec "F:/kodi-rt/tc/rt24d-cr/bin/clang-cl.exe" "@F:/kodi-rt/cross/x86-target-msvc.rsp" -MT "$@"
